package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DownloadProtocol055Test {
 @Test public void multipartRoutingAndSessionAreVisibleBeforeBodyParsing()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){f.requireUploadRoute=true;NasClient c=f.client();assertTrue(c.apiRequest(NasClientConcurrencyTest.API,"create",2,false,Map.of("type","\"file\"","file","[\"torrent\"]","create_list","true","destination","\"video/Filmek\"","size","3"),"fixture.torrent",new byte[]{1,2,3},"torrent").getBoolean("ok"));assertEquals(1,f.requests.get());assertTrue(f.uploadBody.indexOf("name=\"api\"")<f.uploadBody.indexOf("name=\"type\""));assertTrue(f.uploadBody.contains("name=\"torrent\"; filename=\"fixture.torrent\""));assertTrue(f.uploadBody.contains("[\"torrent\"]"));}}
 @Test public void renewedUploadUsesFreshSessionInRouting()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){f.requireUploadRoute=true;f.expiredCode=106;assertTrue(NasClientConcurrencyTest.request(f.client(),false,new byte[]{1}).getBoolean("ok"));assertEquals(2,f.requests.get());assertEquals(2,f.logins.get());assertEquals("fixture-session-2",f.uploadQuery.get("_sid"));assertEquals(1,f.mutations.get());}}
 @Test public void shareAndFolderListingUseDocumentedJsonAdditionalFields()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){f.strictLists=true;NasClient c=f.client();assertTrue(c.list("").isEmpty());assertTrue(c.list("/video/Filmek").isEmpty());}}
 @Test public void rejection101NamesStageWithoutEchoingParametersOrRetrying()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){f.rejectCode=101;try{f.client().apiRequest(NasClientConcurrencyTest.API,"create",2,false,Map.of("destination","private-fixture-path","url","private-fixture-link"),"fixture.torrent",new byte[]{1},"torrent");fail();}catch(NasClient.ApiRejectedException e){assertTrue(e.getMessage().contains("torrent előkészítése"));assertFalse(e.getMessage().contains("private-fixture"));assertFalse(e.getMessage().contains("fixture-session"));}assertEquals(1,f.requests.get());}}
}
